(function(){
  var IMG1='data:image/webp;base64,






';
  var IMG2='data:image/webp;base64,







';
  var I={
    crown:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><path d="M3 8l4.5 4L12 5l4.5 7L21 8l-2 11H5z" fill="currentColor" fill-opacity=".18"/><path d="M5 19h14"/></svg>',
    check:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="m8 12.2 2.7 2.7L16.2 9.5"/></svg>',
    userplus:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="9" cy="8" r="4"/><path d="M2 21c.9-3.9 3.6-6 7-6s6.1 2.1 7 6"/><path d="M19 8v6M16 11h6"/></svg>',
    clock:'<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linecap="round" stroke-linejoin="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 2"/></svg>'
  };
  window.cpMemberBadge=function(light){ return '<span class="cp-mbadge'+(light?' lt':'')+'">'+I.crown+'Réservé aux membres</span>'; };

  var LABEL={ 'profil':'Mon espace', 'eva-taches':'Tâches', 'eva-tracker':'Suivi de ma motivation', 'portfolio':'Portfolio' };
  function curUser(){ try{ return window._fbUser || (window.fbAuth && fbAuth.currentUser) || null; }catch(e){ return null; } }
  function state(){ // true = membre (e-mail confirmé), 'pending' = compte créé mais e-mail à confirmer, false = visiteur, null = vérification en cours
    var u=curUser(); if(u) return u.emailVerified ? true : 'pending';
    if(typeof firebase==='undefined' || !window.fbAuth) return false;
    return window._cpAuthInitialized ? false : null;
  }
  function whenKnown(cb){ var t0=Date.now(); (function w(){ var s=state(); if(s!==null || Date.now()-t0>10000) return cb(s||false); setTimeout(w,120); })(); }

  function close(){ var g=document.getElementById('cp-gift'); if(!g) return; g.classList.add('out'); setTimeout(function(){ if(g.parentNode) g.remove(); },240); document.removeEventListener('keydown',esc); }
  function esc(e){ if(e.key==='Escape') close(); }
  window.cpGiftOpen=function(key){
    var old=document.getElementById('cp-gift'); if(old) old.remove();
    var g=document.createElement('div'); g.id='cp-gift'; g.setAttribute('role','dialog'); g.setAttribute('aria-modal','true');
    g.innerHTML='<div class="cpg-bg"></div><div class="cpg-stage">'
      +'<div class="cpg-scene"><img class="cpg-open" alt="" src="'+IMG2+'"><div class="cpg-flash"></div><img class="cpg-closed" alt="Cadeau" src="'+IMG1+'"></div>'
      +'<div class="cpg-card"><span class="cpg-tag">'+I.crown+'Réservé aux membres</span>'
      +'<div class="cpg-ttl">'+(LABEL[key]||'Espace membre')+'</div>'
      +'<p class="cpg-txt">🎁 Ce service est offert à nos membres. Inscris-toi gratuitement pour en profiter.</p>'
      +'<div class="cpg-btns"><button type="button" class="cpg-yes" data-a="yes">'+I.userplus+'Je m\'inscris</button><button type="button" class="cpg-no" data-a="no">'+I.clock+'Plus tard</button></div></div>'
      +'</div>';
    document.body.appendChild(g);
    requestAnimationFrame(function(){ g.classList.add('open'); });
    g.addEventListener('click',function(e){
      var b=e.target.closest('[data-a]');
      if(b && b.getAttribute('data-a')==='yes'){ close(); setTimeout(function(){ if(window.cpOpenMenu) window.cpOpenMenu('signup'); },200); }
      else if(b || e.target.classList.contains('cpg-bg')) close();
    });
    document.addEventListener('keydown',esc);
  };

  var MAIL='<svg viewBox="0 0 64 64" fill="none"><rect x="8" y="14" width="48" height="36" rx="7" fill="#fff" stroke="#2563eb" stroke-width="3"/><path d="m11 18 21 16 21-16" stroke="#2563eb" stroke-width="3" stroke-linecap="round" stroke-linejoin="round"/><circle cx="50" cy="16" r="9" fill="#059669"/><path d="m46 16 3 3 5-6" stroke="#fff" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"/></svg>';
  window.cpVerifyOpen=function(key){
    var old=document.getElementById('cp-gift'); if(old) old.remove();
    var u=curUser(), em=u&&u.email ? String(u.email).replace(/[&<>"]/g,'') : 'ton adresse';
    var g=document.createElement('div'); g.id='cp-gift'; g.className='cpg-verify'; g.setAttribute('role','dialog'); g.setAttribute('aria-modal','true');
    g.innerHTML='<div class="cpg-bg"></div><div class="cpg-stage">'
      +'<div class="cpg-card" style="opacity:1;animation:cpgCard .5s cubic-bezier(.2,1.2,.3,1) both">'
      +'<div class="cpg-mail">'+MAIL+'</div>'
      +'<div class="cpg-ttl">Vérifie tes e-mails</div>'
      +'<p class="cpg-txt">📩 Une demande de confirmation t\'a été envoyée à <b>'+em+'</b>.<br>Si tu ne la vois pas, regarde dans tes <b>spams</b> ou ta <b>corbeille</b>.'+(key&&LABEL[key]?'<br>Une fois ton e-mail confirmé, <b>'+LABEL[key]+'</b> sera débloqué.':'')+'</p>'
      +'<div class="cpg-note"><b>Bon à savoir :</b> après avoir cliqué sur le lien de l\'e-mail, puis sur <b>« Continuer »</b>, tu arriveras sur CareerPulse. Il faudra sans doute te <b>reconnecter avec ton e-mail et ton mot de passe</b>.<br>Mot de passe oublié ? Pas de panique : le bouton <b>« Mot de passe oublié ? »</b> te permet d\'en créer un nouveau.</div>'
      +'<div class="cpg-btns"><button type="button" class="cpg-yes" data-a="no">'+I.check+'J\'ai compris</button><button type="button" class="cpg-no" data-a="re">'+I.clock+'Renvoyer l\'e-mail</button></div></div></div>';
    document.body.appendChild(g);
    g.addEventListener('click',function(e){
      var b=e.target.closest('[data-a]'), a=b&&b.getAttribute('data-a');
      if(a==='chk'){ if(window.cpCheckVerified) cpCheckVerified(false); }
      else if(a==='re'){ if(window.cpResendVerify) cpResendVerify(); }
      else if(a==='no' || e.target.classList.contains('cpg-bg')) close();
    });
    document.addEventListener('keydown',esc);
  };

  /* Accès protégé : on laisse passer les membres, on invite les visiteurs */
  function deny(key,s){ if(s==='pending') cpVerifyOpen(key); else cpGiftOpen(key); }
  function guard(key, run){ var s=state(); if(s===true) return run(); if(s!==null){ deny(key,s); return; } whenKnown(function(m){ if(m===true) run(); else deny(key,m); }); }
  window.cpMemberGuard=guard;
  var SCREENS={ 'profil':1, 'eva-taches':1, 'eva-tracker':1 };
  function install(){
    var g0=window.go;
    if(typeof g0==='function' && !g0._cpGate){
      var g1=function(id){ var a=arguments, self=this; if(SCREENS[id]) return guard(id,function(){ return g0.apply(self,a); }); return g0.apply(self,a); };
      g1._cpGate=true; window.go=g1; try{ go=g1; }catch(e){}
    }
    ['ewGoDiagnosticChat','ewOpenPortfolioToTab','ewOpenPortfolioInChat'].forEach(function(n){
      var f=window[n]; if(typeof f!=='function' || f._cpGate) return;
      var h=function(){ var a=arguments, self=this; return guard('portfolio',function(){ return f.apply(self,a); }); };
      h._cpGate=true; window[n]=h;
    });
  }
  install(); document.addEventListener('DOMContentLoaded',install); window.addEventListener('load',function(){ setTimeout(install,0); });

  /* Arrivée directe sur une page réservée (lien ou adresse) */
  window.addEventListener('load',function(){
    whenKnown(function(m){
      var ss={}; try{ ss=window.sessionStorage||{}; }catch(e){}
      try{ if(ss.getItem && ss.getItem('cp_verified_now')){ ss.removeItem('cp_verified_now'); var u=curUser(); if(window.ecShowToast) ecShowToast('✅ E-mail confirmé : bienvenue '+((u&&u.displayName)||'')+', tu es membre CareerPulse !'); } }catch(e){}
      if(m===true) return;
      var a=document.querySelector('.screen.active'); var id=a ? a.id.replace('s-','') : '';
      if(SCREENS[id]){ var home=document.getElementById('s-eva') ? 'eva' : 'home'; var g=window.go; if(g) g(home); deny(id,m); return; }
      // juste après l'inscription : on rappelle de confirmer l'e-mail
      try{ if(m==='pending' && ss.getItem && ss.getItem('cp_verify_pending')){ ss.removeItem('cp_verify_pending'); cpVerifyOpen(); var er=ss.getItem('cp_verify_err'); if(er){ ss.removeItem('cp_verify_err'); setTimeout(function(){ if(window.ecShowToast) ecShowToast('L\'e-mail n\'a pas pu partir ('+er+') : clique sur « Renvoyer l\'e-mail ».'); },600); } } }catch(e){}
    });
  });
})();
